	/**
	 * Method to retrieve the Campaign via CampaignFetchOneSummary
	 * @param 	summary CampaignFetchOneSummary
	 * @return 	CampaignFetchOneResponse
	 */
	public Campaign getCampaign( CampaignFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "CampaignFetchOneSummary arg cannot be null" );

		Campaign entity = null;
		UUID id = summary.getCampaignId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Campaign using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Campaigns
	 *
	 * @return 	List<Campaign>
	 */
    public List<Campaign> getAllCampaign() {
		List<Campaign> list = projector.findAll( new FindAllCampaignQuery() );
		return list;
	}

